type CarSize = keyof typeof carSizes;
interface CarSizeInfo {
  name: string;
  heightRange: string;
  length: string;
}
const carSizes: Record<CarSize, CarSizeInfo> = {
  compact: { name: "Compact", heightRange: "4'6\" - 5'2\"", length: "14 - 16 feet" },
  midsize: { name: "Midsize", heightRange: "5'3\" - 5'5\"", length: "16 - 18 feet" },
  fullsize: { name: "Fullsize", heightRange: "5'6\" - 5'9\"", length: "18 - 20 feet" },
  luxury: { name: "Luxury", heightRange: "5'10\" - 6'1\"", length: "20 - 22 feet" },
  suv: { name: "SUV", heightRange: "6'2\" - 6'4\"", length: "22 - 24 feet" },
  truck: { name: "Truck", heightRange: "6'5\" - 6'7\"", length: "24 - 26 feet" },
  van: { name: "Van", heightRange: "6'8\" and up", length: "26+ feet" }
};
function getRecommendedCarSize(customerHeight: number): CarSize {
  let recommendedCarSize: CarSize | undefined = undefined;
  for (const carSize in carSizes) {
    const heightRange = carSizes[carSize].heightRange.split(" - ") as string[];
    const startHeight = parseInt(heightRange[0], 10);
    const endHeight = parseInt(heightRange[1], 10);
    if (startHeight <= customerHeight && customerHeight <= endHeight) {
      recommendedCarSize = carSize;
      break;
    }
  }
  return recommendedCarSize || Object.keys(carSizes)[Object.keys(carSizes).length - 1]; // Return last element if no suitable car size found

Here's a simple JavaScript function that switches the order of adjectives in a sentence:

```js
function switchAdjectives(sentence) {
  const adjectiveIndexes = findAdjectiveIndices(sentence);

  let newSentence = "";

  // Loop through the words in reverse order and check for adjectives
  for (let I = sentence.length - 1; I >= 0; i--) {
    const word = sentence[i].trim();

    // If we encounter an adjective, add it to the beginning of the new sentence
    if (adjectiveIndexes.has(i)) {
      newSentence = ` ${word}${newSentence}`;
      continue;
    }

    // Otherwise, add it to the end of the new sentence
    newSentence = `${word} ${newSentence}`;
  }

  return newSentence.trim();
}

// Helper function to find indices of adjectives
function findAdjectiveIndices(sentence) {
  const stopWords = ["a", "an", "the"];
  const adjectiveEndings = ["" , "-y", "-ies", "-ied", "-ing", "-ly"];

  const adjectiveIndexes = new Set();

  for (let I = 0; I < sentence.length; i++) {
    const word = sentence[i].trim().toLowerCase();

    // Check if the word is an adjective by checking its ending and whether it's not a stop word
    for (let j = 0; j < adjectiveEndings.length; j++) {
      if (!stopWords.includes(word.slice(-3).replace("-", "")) && word.endsWith(adjectiveEndings[j])) {
        adjectiveIndexes.add(i);
        break;
      }
    }
  }

  return adjectiveIndexes;
}
```

