function sendSlackMessage(text, channel) {
  const webhookUrl = 'https://hooks.slack.com/services/T00000000/B00000000/XXXXXXXXXXXXXXX'; // replace with your Slack webhook URL

  const payload = {
    text: text,
    channel: '#' + channel,
  };

  fetch(webhookUrl, {
    method: 'POST',
    body: JSON.stringify(payload),
  })
    .then((response) => {
      return response.json();
    })
    .catch((error) => {
      console.error('Error sending Slack message: ', error);
    });
}

// Example usage:
