```go
func genAvroSchema(structName string) (*avro.Schema, error) {
	// Parse the Go source file
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "path/to/source.go", parser.ParseComments, parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("error parsing file: %w", err)
	}

	// Find the type declaration for the selected struct
	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					if strings.Contains(s.Name.Name, structName) {
						return genAvroType(s.Type), nil
					}
				}
			}
		}
	}

	// Struct not found
	return nil, fmt.Errorf("struct %s not found in file", structName)
}

